k", "southwark-clubs", "stanton-clubs", "marian-anderson-clubs", "childs-clubs", "bache-martin-clubs", "greenfield-clubs", "east-passyunk-rec", "philadelphia-martial-arts-academy", "fitness-alive-south-philly", "christian-street-ymca", "hudson-table-philadelphia", "rizzo-rink", "flips-4-kidz", "equilibrium-dance-academy", "blue-chip-flag-south-philadelphia", "kumon-south-philadelphia", "pennsport-school-of-dance", "philly-pack", "magic-gardens-family-jams", "phield-house", "philadelphia-school-of-circus-arts", "schuylkill-center", "flipout-productions", "elite-sports-factory", "movement-callowhill", "the-philadelphia-school", "nlarts", "philadelphia-youth-basketball", "awbury-arboretum", "skilladelphia", "philly-art-center-mt-airy", "philly-art-center-fairmount");
$SCHOOLS = array("nebinger", "meredith", "coppin", "vare-washington", "stanton", "mccall", "kirkbride", "southwark", "columbus-charter", "marian-anderson", "lingelbach", "houston", "childs", "bache-martin", "independence-charter", "greenfield");
$GRADES = array("PK", "K", "1", "2", "3", "4", "5", "6", "7", "8");

function fail($msg, $code) {
  http_response_code($code);
  header('Content-Type: text/html; charset=utf-8');
  echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Not sent</title><link rel="stylesheet" href="../assets/site.css?v=50bf7248"></head><body><main class="wrap"><h1>That did not send</h1><p>' . htmlspecialchars($msg, ENT_QUOTES, 'UTF-8') . '</p><p><a href="javascript:history.back()">Go back to the form</a></p></main></body></html>';
  exit;
}
function field($key, $max) {
  $v = (isset($_POST[$key]) && is_string($_POST[$key])) ? trim($_POST[$key]) : '';
  $v = str_replace(chr(0), '', $v);
  return function_exists('mb_substr') ? mb_substr($v, 0, $max, 'UTF-8') : substr($v, 0, $max);
}
function one_line($v) {
  return trim(preg_replace('/[\r\n\t]+/', ' ', $v));
}

if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
  header('Location: ./', true, 303);
  exit;
}
// A hidden field people never see. If it is filled in, a bot did it: act as if it worked.
if (field('company', 200) !== '') {
  header('Location: thanks/', true, 303);
  exit;
}

$program = one_line(field('program', 80));
$school = one_line(field('school', 40));
$stars = (int) field('stars', 2);
$name = one_line(field('name', 40));
$email = one_line(field('email', 150));
$comment = field('comment', 1200);

if (!in_array($program, $PROGRAMS, true) || !in_array($school, $SCHOOLS, true)) {
  fail('Please choose the program and school from the lists.', 400);
}
if ($stars < 1 || $stars > 5) {
  fail('Please choose a rating from 1 to 5 stars.', 400);
}
if (strlen($comment) < 20) {
  fail('Please write a sentence or two so other families know what to expect.', 400);
}
if ($name === '') {
  fail('Please add your first name. It is shown with your review.', 400);
}
if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
  fail('Please add a working email address. It is never shown.', 400);
}
if (field('firsthand', 5) !== 'yes') {
  fail('Please confirm this is your own experience.', 400);
}
// In a child's words: the grade is needed, the first name only when the parent chose to show it.
$kid = null;
if (field('kid', 5) === 'yes') {
  $grade = one_line(field('kidgrade', 4));
  if (!in_array($grade, $GRADES, true)) {
    fail('Please choose your child’s grade.', 400);
  }
  $kid = array('grade' => $grade);
  $kidName = one_line(field('kidname', 20));
  if (field('kidshow', 5) === 'yes' && $kidName !== '' && preg_match('/^[\p{L}\p{M}][\p{L}\p{M} \'’.-]{0,19}$/u', $kidName)) {
    $kid['name'] = $kidName;
  }
}
if (substr_count(strtolower($comment), 'http') > 1) {
  fail('Reviews cannot include links. Please remove them and try again.', 400);
}

$record = array(
  'programId' => $program,
  'school' => $school,
  'name' => $name,
  'stars' => $stars,
  'comment' => trim(preg_replace('/\s+/', ' ', $comment)),
  'date' => date('Y-m-d'),
);
if ($kid !== null) {
  $record['kid'] = $kid;
}
$entry = json_encode($record, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);

$body = ($kid !== null ? "New review IN A KID'S WORDS (" . (isset($kid['name']) ? $kid['name'] . ', ' : 'name not shown, ') . 'grade ' . $kid['grade'] . "), waiting for your approval.\n\n" : "New review, waiting for your approval.\n\n")
  . "Program: $program\n"
  . "School: $school\n"
  . "Stars: $stars\n"
  . "From: $name <$email>\n\n"
  . "$comment\n\n"
  . "To publish it, add this entry to data/reviews.json (inside the square brackets, with a comma between entries):\n\n"
  . "$entry\n";

$subject = one_line("[$SITE] Review: $program ($stars stars)");
$headers = array(
  'From: ' . $SITE . ' <' . $TO . '>',
  'Reply-To: ' . $email,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset=UTF-8',
);

$sent = pas_postmark($SITE, $TO, $TO, $subject, $body, '', isset($email) ? (string) $email : '') === 1 || @mail($TO, '=?UTF-8?B?' . base64_encode($subject) . '?=', $body, implode("\r\n", $headers));
$log = dirname($_SERVER['DOCUMENT_ROOT']) . '/phillyafterschool-reviews.log';
$saved = @file_put_contents($log, date('c') . ($sent ? ' (emailed)' : ' (EMAIL FAILED)') . "\n" . $body . "----\n", FILE_APPEND | LOCK_EX);

if (!$sent && $saved === false) {
  fail('Something went wrong on our side. Please email ' . $TO . ' instead.', 500);
}
header('Location: thanks/', true, 303);
exit;
